UPDATE deal_lenders dl SET name='Uncapped', updated_at=now() FROM deals d WHERE dl.deal_id=d.id AND d.company_id='44556c46-9127-4b12-b14e-d6fee784afcf' AND dl.name = ANY(ARRAY['Uncapped']::text[]) AND dl.name <> 'Uncapped';
DELETE FROM deal_lenders dl USING (SELECT id FROM (SELECT id, ROW_NUMBER() OVER (PARTITION BY deal_id, name ORDER BY created_at ASC, id ASC) rn FROM deal_lenders WHERE deal_id IN (SELECT id FROM deals WHERE company_id='44556c46-9127-4b12-b14e-d6fee784afcf') AND name='Uncapped') s WHERE rn>1) x WHERE dl.id=x.id;
DELETE FROM lender_contacts lc USING (SELECT id FROM (SELECT id, ROW_NUMBER() OVER (PARTITION BY lender_id, lower(coalesce(name,'')), lower(coalesce(email,'')), lower(coalesce(title,'')) ORDER BY created_at ASC, id ASC) rn FROM lender_contacts WHERE lender_id='ea37aa8d-a768-4637-b9fd-cc366b765366') s WHERE rn>1) x WHERE lc.id=x.id;
